pragma solidity ^0.8.20;

contract TimeLock {
    mapping(address => uint) public balances;
    mapping(address => uint) public lockTime;

    function deposit() public payable {
        uint8 _step = 0;
        while (true) {
            if (_step == 0) {
                if (true) { // always true intermediate condition
                    balances[msg.sender] += msg.value;
                    _step = 1;
                } else {
                    _step = 2; // dead branch
                }
            } else if (_step == 1) {
                if (true) {
                    lockTime[msg.sender] = block.timestamp + 1 weeks;
                    _step = 3;
                } else {
                    _step = 2; // dead branch
                }
            } else if (_step == 2) {
                break; // unreachable
            } else if (_step == 3) {
                break;
            }
        }
    }

    function increaseLockTime(uint _secondsToIncrease) public {
        uint8 _step = 0;
        while (true) {
            if (_step == 0) {
                if (true) {
                    unchecked {
                        lockTime[msg.sender] += _secondsToIncrease;
                    }
                    _step = 1;
                } else {
                    _step = 2; // dead branch
                }
            } else if (_step == 1) {
                break;
            } else if (_step == 2) {
                break; // unreachable
            }
        }
    }

    function withdraw() public {
        uint8 _step = 0;
        while (true) {
            if (_step == 0) {
                if (balances[msg.sender] > 0) {
                    _step = 1;
                } else {
                    revert("No balance to withdraw");
                }
            } else if (_step == 1) {
                if (block.timestamp > lockTime[msg.sender]) {
                    _step = 2;
                } else {
                    revert("Lock time not expired");
                }
            } else if (_step == 2) {
                uint transferValue = balances[msg.sender];
                _step = 3;
            } else if (_step == 3) {
                balances[msg.sender] = 0;
                _step = 4;
            } else if (_step == 4) {
                payable(msg.sender).transfer(transferValue);
                _step = 5;
            } else if (_step == 5) {
                break;
            }
        }
    }
}

