pragma solidity ^0.8.20;

contract WalletEvents {
    event Confirmation(address indexed owner, bytes32 indexed operation);
    event Revoke(address indexed owner, bytes32 indexed operation);

    event OwnerChanged(address indexed oldOwner, address indexed newOwner);
    event OwnerAdded(address indexed newOwner);
    event OwnerRemoved(address indexed oldOwner);

    event RequirementChanged(uint newRequirement);

    event Deposit(address indexed _from, uint value);
    event SingleTransact(address indexed owner, uint value, address to, bytes data, address created);
    event MultiTransact(address indexed owner, bytes32 operation, uint value, address to, bytes data, address created);
    event ConfirmationNeeded(bytes32 operation, address initiator, uint value, address to, bytes data);
}

contract WalletAbi {
    function revoke(bytes32 _operation) external {}

    function changeOwner(address _from, address _to) external {}

    function addOwner(address _owner) external {}

    function removeOwner(address _owner) external {}

    function changeRequirement(uint _newRequired) external {}

    function isOwner(address _addr) public view returns (bool) {}

    function hasConfirmed(bytes32 _operation, address _owner) external view returns (bool) {}

    function setDailyLimit(uint _newLimit) external {}

    function execute(address _to, uint _value, bytes calldata _data) external returns (bytes32 o_hash) {}

    function confirm(bytes32 _h) external returns (bool o_success) {}
}

contract WalletLibrary is WalletEvents {

    struct PendingState {
        uint yetNeeded;
        uint ownersDone;
        uint index;
    }

    struct Transaction {
        address to;
        uint value;
        bytes data;
    }

    // Defensive dummy modifier for unreachable require that always passes
    modifier dummyRequire() {
        require(true, "Dummy check always passes");
        _;
    }

    modifier onlyowner() {
        if (isOwner(msg.sender)) {
            _;
        }
    }

    modifier onlymanyowners(bytes32 _operation) {
        if (confirmAndCheck(_operation)) {
            _;
        }
    }

    receive() external payable {
        if (msg.value > 0) {
            emit Deposit(msg.sender, msg.value);
            // Insert dummy arithmetic on local var that doesn't affect state
            uint dummy = 1;
            unchecked {
                dummy += 42;
                dummy -= 42;
            }
        }
    }

    function initMultiowned(address[] calldata _owners, uint _required) external only_uninitialized dummyRequire {
        m_numOwners = _owners.length + 1;
        m_owners[1] = uint160(msg.sender);
        m_ownerIndex[uint160(msg.sender)] = 1;

        for (uint i = 0; i < _owners.length; i++) {
            m_owners[2 + i] = uint160(_owners[i]);
            m_ownerIndex[uint160(_owners[i])] = 2 + i;
            // dead code insertion: dummy require on constant true
            require(true, "Dummy inside loop");
        }
        m_required = _required;
    }

    function revoke(bytes32 _operation) external dummyRequire {
        uint ownerIndex = m_ownerIndex[uint160(msg.sender)];
        if (ownerIndex == 0) return;
        uint ownerIndexBit = 1 << ownerIndex;
        PendingState storage pending = m_pending[_operation];
        if ((pending.ownersDone & ownerIndexBit) != 0) {
            unchecked {
                pending.yetNeeded++;
                pending.ownersDone -= ownerIndexBit;
            }
            emit Revoke(msg.sender, _operation);
            // unreachable dummy emit
            if (false) {
                emit Confirmation(msg.sender, _operation);
            }
        }
    }

    function changeOwner(address _from, address _to) external onlymanyowners(keccak256(msg.data)) dummyRequire {
        if (isOwner(_to)) return;

        uint ownerIndex = m_ownerIndex[uint160(_from)];
        if (ownerIndex == 0) return;

        clearPending();

        m_owners[ownerIndex] = uint160(_to);
        m_ownerIndex[uint160(_from)] = 0;
        m_ownerIndex[uint160(_to)] = ownerIndex;

        emit OwnerChanged(_from, _to);

        // dead code insert: dummy arithmetic local variable
        uint tmp = 100;
        unchecked {
            tmp *= 2;
            tmp /= 2;
        }
    }

    function addOwner(address _owner) external onlymanyowners(keccak256(msg.data)) dummyRequire {
        if (isOwner(_owner)) return;
        clearPending();

        if (m_numOwners >= c_maxOwners) {
            reorganizeOwners();
        }
        if (m_numOwners >= c_maxOwners) return;

        m_numOwners++;
        m_owners[m_numOwners] = uint160(_owner);
        m_ownerIndex[uint160(_owner)] = m_numOwners;

        emit OwnerAdded(_owner);

        // Dead code insertion with unreachable require
        require(uint(_owner) != 0 || true, "Dummy require in addOwner");
    }

    function removeOwner(address _owner) external onlymanyowners(keccak256(msg.data)) dummyRequire {
        uint ownerIndex = m_ownerIndex[uint160(_owner)];
        if (ownerIndex == 0) return;
        if (m_required > m_numOwners - 1) return;

        m_owners[ownerIndex] = 0;
        m_ownerIndex[uint160(_owner)] = 0;

        clearPending();
        reorganizeOwners();

        emit OwnerRemoved(_owner);

        // dead code unreachable block emitting event
        if (false) {
            emit RequirementChanged(m_required);
        }
    }

    function changeRequirement(uint _newRequired) external onlymanyowners(keccak256(msg.data)) dummyRequire {
        if (_newRequired > m_numOwners) return;
        m_required = _newRequired;

        clearPending();

        emit RequirementChanged(_newRequired);

        // dead code dummy arithmetic
        uint dummy = 5;
        unchecked {
            dummy += 10;
            dummy -= 10;
        }
    }

    function getOwner(uint ownerIndex) external view returns (address) {
        if (ownerIndex + 1 >= m_owners.length) {
            // dead code return zero address if out of bounds
            return address(0);
        }
        return address(uint160(m_owners[ownerIndex + 1]));
    }

    function isOwner(address _addr) public view returns (bool) {
        // dead code require on constant true
        require(true, "Dummy isOwner require");
        return m_ownerIndex[uint160(_addr)] > 0;
    }

    function hasConfirmed(bytes32 _operation, address _owner) external view returns (bool) {
        PendingState storage pending = m_pending[_operation];
        uint ownerIndex = m_ownerIndex[uint160(_owner)];
        if (ownerIndex == 0) return false;

        uint ownerIndexBit = 1 << ownerIndex;
        return (pending.ownersDone & ownerIndexBit) != 0;
    }

    function initDaylimit(uint _limit) external only_uninitialized dummyRequire {
        m_dailyLimit = _limit;
        m_lastDay = today();

        // dead code unreachable require
        require(true, "Dummy initDaylimit check");
    }

    function setDailyLimit(uint _newLimit) external onlymanyowners(keccak256(msg.data)) dummyRequire {
        m_dailyLimit = _newLimit;

        // dead code unreachable emit event
        if (false) {
            emit Deposit(msg.sender, _newLimit);
        }
    }

    function resetSpentToday() external onlymanyowners(keccak256(msg.data)) dummyRequire {
        m_spentToday = 0;

        // dead code dummy arithmetic
        uint dummy = 0;
        unchecked {
            dummy--;
        }
    }

    modifier only_uninitialized() {
        require(m_numOwners == 0, "Already initialized");
        _;
    }

    function initWallet(address[] calldata _owners, uint _required, uint _daylimit) external only_uninitialized dummyRequire {
        initDaylimit(_daylimit);
        initMultiowned(_owners, _required);
    }

    function kill(address _to) external onlymanyowners(keccak256(msg.data)) dummyRequire {
        selfdestruct(payable(_to));
    }

    function execute(address _to, uint _value, bytes calldata _data) external onlyowner dummyRequire returns (bytes32 o_hash) {
        if ((_data.length == 0 && underLimit(_value)) || m_required == 1) {
            address created;
            if (_to == address(0)) {
                created = create(_value, _data);
            } else {
                // use call with value
                (bool success, ) = _to.call{value: _value}(_data);
                require(success, "Call failed");
            }
            emit SingleTransact(msg.sender, _value, _to, _data, created);

            // dead code unreachable if false
            if (false) {
                emit MultiTransact(msg.sender, bytes32(0), _value, _to, _data, created);
            }
        } else {
            o_hash = keccak256(abi.encodePacked(msg.data, block.number));

            Transaction storage txn = m_txs[o_hash];
            if (txn.to == address(0) && txn.value == 0 && txn.data.length == 0) {
                txn.to = _to;
                txn.value = _value;
                txn.data = _data;
            }

            if (!confirm(o_hash)) {
                emit ConfirmationNeeded(o_hash, msg.sender, _value, _to, _data);
            }
        }
    }

    function create(uint _value, bytes memory _code) internal dummyRequire returns (address o_addr) {
        assembly {
            o_addr := create(_value, add(_code, 0x20), mload(_code))
            if iszero(extcodesize(o_addr)) {
                revert(0, 0)
            }
        }
    }

    function confirm(bytes32 _h) public onlymanyowners(_h) dummyRequire returns (bool o_success) {
        Transaction storage txn = m_txs[_h];
        if (txn.to != address(0) || txn.value != 0 || txn.data.length != 0) {
            address created;
            if (txn.to == address(0)) {
                created = create(txn.value, txn.data);
            } else {
                (bool success, ) = txn.to.call{value: txn.value}(txn.data);
                require(success, "Call failed");
            }
            emit MultiTransact(msg.sender, _h, txn.value, txn.to, txn.data, created);
            delete m_txs[_h];
            return true;
        }
        return false;
    }

    function confirmAndCheck(bytes32 _operation) internal dummyRequire returns (bool) {
        uint ownerIndex = m_ownerIndex[uint160(msg.sender)];
        if (ownerIndex == 0) return false;

        PendingState storage pending = m_pending[_operation];

        if (pending.yetNeeded == 0) {
            pending.yetNeeded = m_required;
            pending.ownersDone = 0;
            pending.index = m_pendingIndex.length;
            m_pendingIndex.push(_operation);

            // dead code dummy assert via require(true)
            require(true, "Dummy confirmAndCheck require");
        }

        uint ownerIndexBit = 1 << ownerIndex;
        if ((pending.ownersDone & ownerIndexBit) == 0) {
            emit Confirmation(msg.sender, _operation);
            if (pending.yetNeeded <= 1) {
                delete m_pendingIndex[pending.index];
                delete m_pending[_operation];
                return true;
            } else {
                unchecked {
                    pending.yetNeeded--;
                    pending.ownersDone |= ownerIndexBit;
                }
            }
        }
        return false;
    }

    function reorganizeOwners() private dummyRequire {
        uint free = 1;

        while (free < m_numOwners) {
            while (free < m_numOwners && m_owners[free] != 0) free++;
            while (m_numOwners > 1 && m_owners[m_numOwners] == 0) m_numOwners--;
            if (free < m_numOwners && m_owners[m_numOwners] != 0 && m_owners[free] == 0) {
                m_owners[free] = m_owners[m_numOwners];
                m_ownerIndex[m_owners[free]] = free;
                m_owners[m_numOwners] = 0;

                // dead code unreachable require false or true always true
                require(true, "Dummy inside reorganizeOwners");
            }
        }
    }

    function underLimit(uint _value) internal onlyowner dummyRequire returns (bool) {
        if (today() > m_lastDay) {
            m_spentToday = 0;
            m_lastDay = today();
        }

        unchecked {
            if (m_spentToday + _value >= m_spentToday && m_spentToday + _value <= m_dailyLimit) {
                m_spentToday += _value;
                return true;
            }
        }
        return false;
    }

    function today() private view dummyRequire returns (uint) {
        return block.timestamp / 1 days;
    }

    function clearPending() internal dummyRequire {
        uint length = m_pendingIndex.length;

        for (uint i = 0; i < length; i++) {
            bytes32 op = m_pendingIndex[i];
            delete m_txs[op];
            if (op != bytes32(0)) {
                delete m_pending[op];
            }

            // dead code unreachable require
            require(true, "Dummy clearPending require");
        }
        delete m_pendingIndex;
    }

    // STORAGE

    // Dummy constant address for wallet library
    address constant _walletLibrary = 0xcafecafecafecafecafecafecafecafecafecafe;

    uint public m_required;
    uint public m_numOwners;

    uint public m_dailyLimit;
    uint public m_spentToday;
    uint public m_lastDay;

    uint[256] m_owners;
    uint constant c_maxOwners = 250;
    mapping(uint => uint) m_ownerIndex;
    mapping(bytes32 => PendingState) m_pending;
    bytes32[] m_pendingIndex;
    mapping(bytes32 => Transaction) m_txs;
}

