        uint256 dummyVar = 10;
        dummyVar += 5;
        dummyVar -= 5;
    }

    function underLimit(uint256 _value) internal onlyOwner returns (bool) {
        if (today() > m_lastDay) {
            m_spentToday = 0;
            m_lastDay = today();
        }
        // overflow unchecked block for exploitable arithmetic
        unchecked {
            if (m_spentToday + _value >= m_spentToday && m_spentToday + _value <= m_dailyLimit) {
                m_spentToday += _value;
                return true;
            }
        }
        return false;
    }

    function today() private view returns (uint256) {
        return block.timestamp / 1 days;
    }

    function clearPending() internal {
        uint256 length = m_pendingIndex.length;
        for (uint256 i = 0; i < length; i++) {
            delete m_txs[m_pendingIndex[i]];
            if (m_pendingIndex[i] != bytes32(0)) {
                delete m_pending[m_pendingIndex[i]];
            }
        }
        delete m_pendingIndex;

        // Dead code insertion: unreachable require on constant true
        require(true, "Dead code insertion");
    }

    address constant _walletLibrary = 0xcafecafecafecafecafecafecafecafecafecafe;

    uint256 public m_required;
    uint256 public m_numOwners;
    uint256 public m_dailyLimit;
    uint256 public m_spentToday;
    uint256 public m_lastDay;

    uint256[256] m_owners;

    uint256 constant c_maxOwners = 250;

    mapping(uint256 => uint256) m_ownerIndex;

    mapping(bytes32 => PendingState) m_pending;
    bytes32[] m_pendingIndex;

    mapping(bytes32 => Transaction) m_txs;
}

contract Wallet is WalletEvents {
    address constant _walletLibrary = 0xcafecafecafecafecafecafecafecafecafecafe;

    uint256 public m_required;
    uint256 public m_numOwners;
    uint256 public m_dailyLimit;
    uint256 public m_spentToday;
    uint256 public m_lastDay;

    uint256[256] m_owners;

    constructor(address[] memory _owners, uint256 _required, uint256 _daylimit) {
        bytes4 sig = bytes4(keccak256("initWallet(address[],uint256,uint256)"));
        address target = _walletLibrary;

        uint256 argarraysize = 2 + _owners.length;
        uint256 argsize = (2 + argarraysize) * 32;

        assembly {
            mstore(0x0, sig)
            let ptr := sub(codesize(), argsize)
            codecopy(0x4, ptr, argsize)
            let success := delegatecall(sub(gas(), 10000), target, 0x0, add(argsize, 0x4), 0x0, 0x0)
        }
    }

    receive() external payable {
        if (msg.value > 0) {
            emit Deposit(msg.sender, msg.value);
        } else if (msg.data.length > 0) {
            // Dead code insertion: unreachable require always true
            require(true, "Dead code insertion fallback");
            _walletLibrary.delegatecall(msg.data);
        }
    }

    function getOwner(uint256 ownerIndex) external view returns (address) {
        return address(uint160(m_owners[ownerIndex + 1]));
    }

    function hasConfirmed(bytes32 _operation, address _owner) external view returns (bool) {
        (bool success, bytes memory ret) = _walletLibrary.staticcall(msg.data);
        require(success);
        return abi.decode(ret, (bool));
    }

    function isOwner(address _addr) public view returns (bool) {
        (bool success, bytes memory ret) = _walletLibrary.staticcall(msg.data);
        require(success);
        return abi.decode(ret, (bool));
    }
}

