import "forge-std/Test.sol";

pragma solidity ^0.8.33;

contract VulnerableUncheckedCall {
    event CallAttempted(address target, bool success);

    // Vulnerable function: ignores success of low-level call
    function sendEther(address payable target, uint256 amount) external payable {
        // Unchecked low-level call
        (bool success, ) = target.call{value: amount}("");
        emit CallAttempted(target, success);
        // Does not revert on failure
    }

    receive() external payable {}
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecting fallback");
    }
}

contract ExploitTest is Test {
    VulnerableUncheckedCall vuln;
    Rejecter rejecter;

    function setUp() public {
        // Deploy the vulnerable contract
        vuln = new VulnerableUncheckedCall();
        // Fund the vulnerable contract with 1 ether so it can send
        vm.deal(address(this), 1 ether);
        (bool sent, ) = payable(address(vuln)).call{value: 1 ether}("");
        require(sent, "Funding vuln failed");

        // Deploy the Rejecter contract
        rejecter = new Rejecter();
    }

    // Allow this contract to receive ether for funding
    receive() external payable {}

    function test_exploit_unchecked_low_level_calls() public {
        // Check initial balance of vuln contract
        uint256 initialBalance = address(vuln).balance;
        assertGt(initialBalance, 0);

        // Call the vulnerable function to send ether to Rejecter, which will revert on fallback
        // The vuln contract does not revert, ignoring the failure
        vm.prank(address(this));
        vuln.sendEther{value: 0.1 ether}(payable(address(rejecter)), 0.1 ether);

        // Assert the vulnerable contract balance decreased by 0.1 ether
        uint256 afterBalance = address(vuln).balance;
        assertEq(afterBalance, initialBalance - 0.1 ether);

        // Assert that the transaction succeeded despite the inner call reverting
        // The fact that the vuln contract balance decreased despite revert proves unchecked call
        // We assert that the outer call did not revert by reaching this point
        assertTrue(true);
    }
}
